import { useEffect, useRef } from "react";
import { Card, CardHeader, CardRow, ReadFreshness, ReadLine, SectionPill } from "ui";

const sections = [
  { id: "p9-unexplained", label: "No record", count: 4, tone: "warn" as const },
  { id: "p9-missing", label: "Missing in Zitadel", count: 2, tone: "danger" as const },
  { id: "p9-explained", label: "Explained", count: 31 },
];
const ago = (min: number) => new Date(Date.now() - min * 60_000).toISOString();

/** The pill only shows once the read line has scrolled away, so the story scrolls its own container past it. */
export const WhileScrolling = () => {
  const box = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const t = setTimeout(() => {
      if (box.current) box.current.scrollTop = 230;
    }, 60);
    return () => clearTimeout(t);
  }, []);
  return (
    <div id="app-scroll" ref={box} style={{ height: 360, overflowY: "auto", position: "relative", padding: "0 4px" }}>
      <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
        <SectionPill label="Sections of drift" sections={sections} />
        <ReadLine label="Sections of drift" sections={sections}>
          <ReadFreshness state={{ readAt: ago(1), current: true }} subject="What Zitadel confirmed" />
        </ReadLine>
        {sections.map((s) => (
          <div key={s.id} id={s.id}>
            <Card>
              <CardHeader title={s.label} count={s.count} />
              <CardRow first>
                <div style={{ height: 70 }}>Roman Reigns · Laser cutter</div>
              </CardRow>
              <CardRow>
                <div style={{ height: 70 }}>Damian Priest · CNC router</div>
              </CardRow>
            </Card>
          </div>
        ))}
      </div>
    </div>
  );
};
